/**
 * @method
 * @name cf_ExportExcel
 * @description  Grid의 Data 를 Excel 파일로 Export 한다
 * @param sGridList - 출력대상 Grid ID 문자열 List (grdA,grdB,grdC)
 * @param sSheetNameList - Excel 파일에 생성될 Sheet명 문자열 List (sheetA,sheetB,sheetC)
 * @param sFileName - 저장할 파일명
 * @param userOpt - 사용자 excelInfo 추가 옵션 array에 그리드별 옵션 예) userOpt = [{addOpt : 1, addOpt2 : 2}] // 첫번째 그리드의 추가 옵션
 * @return
 */
scwin.cf_ExportExcel = function(sGridList, sSheetNameList, sFileName, userOpt = [])  {

	if (!sFileName) {
        //menuId로 대체
		sFileName = $p.getFrame().menuid;
	}

    // id가 a,b,c,d,e인 5개 컬럼이 존재하는 그리드
    var options = {
        common: {
            fileName : sFileName + ".xls",
            showProcess : true,
            multipleSheet : true
        },
        excelInfo: []
    };

	var aGrid = sGridList.split(",");
	var aSheetName = sSheetNameList.split(",");	

    for (var i=0; i<aGrid.length; i++) {

        options.excelInfo.push({
            //gridId : gridView01.id,
            gridId : aGrid[i],
            sheetName : aSheetName[i],
            type : "1",
            startRowIndex : 0,
            startColumnIndex : 0,
            headerColor : "#D3D3D3",
			colMerge : true,
			mergeCell : true,
            useStyle:true
        });
		options.excelInfo[i] = {...options.excelInfo[i], ...(userOpt[i] ||{})}

        //20250820 스타일 초기화 - 주석 풀경우 정상동작하지만 화면깨짐
        //var objGrid = scwin.object(aGrid[i]);
        //objGrid.setGridStyle(objGrid.getGridStyle());
    }

    WebSquare.util.multipleExcelDownload( options );

};

scwin.textbox1_onclick = function(e) {
	var options = {
        fileName : "정렬적용.xls",
        showProcess : true,
        multipleSheet : true};
    gridView01.advancedExcelDownload(options)
};

scwin.textbox2_onclick = function(e) {
	scwin.cf_ExportExcel("gridView01", "sheet1", "정렬미적용");
};
